def comps(g,val):
    H,W=len(g),len(g[0]); seen=[[0]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and not seen[r][c]:
                st=[(r,c)]; comp=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in comp: continue
                    comp.add((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==val and (x,y) not in comp: st.append((x,y))
                out.append(comp)
    return out
