def f(g):
    H=len(g);W=len(g[0])
    bandcells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==3]
    if not bandcells: return [row[:] for row in g]
    br=[r for r,c in bandcells]; bc=[c for r,c in bandcells]
    top,bot=min(br),max(br); left,right=min(bc),max(bc)
    out=[row[:] for row in g]
    # heads = top-left cell of each 8-comp -> 8
    for oc in comps8(g,val=2):
        head=min(oc)
        out[head[0]][head[1]]=8
    stamps=[]
    for oc in comps8(g,val=2):
        hmin=min(r for r,c in oc); hcol=min(c for r,c in oc)
        best=None
        for dr in range(-H,H+1):
            for dc in range(-W,W+1):
                t={(r+dr,c+dc) for r,c in oc}
                if all(top<=r<=bot and left<=c<=right for r,c in t):
                    # flush against nearest edge? prefer touching an edge
                    touches=any(r==top or r==bot for r,c in t)+any(c==left or c==right for r,c in t)
                    key=(not touches,-(hcol),-dr)
                    if best is None or key<best[0]: best=(key,t)
        if best:
            stamps.append(best)
    for _,t in stamps:
        for r,c in t: out[r][c]=2
    for r in range(top,bot+1):
        for c in range(left,right+1):
            if out[r][c]==3: out[r][c]=0
    return out
